"""Filling a .docx template: the expression side.

Jinja2 does the work when it is installed; otherwise the small engine here
handles variables, ``for``, ``if``/``elif``/``else``, ``loop.index`` and the
common filters.  Either way values are XML-escaped on the way in, because what
is being rendered is WordprocessingML, not text.
"""
from __future__ import annotations

import re

def _escape(value) -> str:
    text = '' if value is None else str(value)
    return (text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;'))


def _as_docx_text(value) -> str:
    """Escape a value and turn newlines and tabs into real Word breaks."""
    text = _escape(value)
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    text = text.replace('\n', '</w:t><w:br/><w:t xml:space="preserve">')
    text = text.replace('\t', '</w:t><w:tab/><w:t xml:space="preserve">')
    return text


def render_string(xml: str, context: dict, jinja: bool) -> str:
    if jinja:
        try:
            return _render_jinja(xml, context)
        except ImportError:
            pass
    return MiniTemplate(xml).render(context)


def _render_jinja(xml: str, context: dict) -> str:
    from jinja2 import Environment, Undefined

    def finalize(value):
        if value is None or isinstance(value, Undefined):
            return ''
        return value

    env = Environment(autoescape=False, finalize=finalize,
                      undefined=Undefined, keep_trailing_newline=True)
    env.filters['xml'] = _as_docx_text
    template = env.from_string(_auto_escape(xml))
    return template.render(**(context or {}))


def _auto_escape(xml: str) -> str:
    """Route every ``{{ expr }}`` through the XML-escaping filter."""
    def repl(match):
        inner = match.group(1).strip()
        if not inner or inner.endswith('|xml') or inner.startswith('#'):
            return match.group(0)
        return '{{ (%s)|xml }}' % inner
    return re.sub(r'\{\{(.+?)\}\}', repl, xml, flags=re.S)


class MiniTemplate:
    """A small stand-in for Jinja2: variables, for, if/elif/else, filters."""

    TOKEN_RE = re.compile(r'(\{\{.*?\}\}|\{%.*?%\}|\{#.*?#\})', re.S)

    def __init__(self, source: str):
        self.nodes = self._parse(self.TOKEN_RE.split(source))

    def _parse(self, tokens):
        stack = [[]]
        for token in tokens:
            if not token:
                continue
            if token.startswith('{{') and token.endswith('}}'):
                stack[-1].append(('var', token[2:-2].strip()))
            elif token.startswith('{#'):
                continue
            elif token.startswith('{%') and token.endswith('%}'):
                statement = token[2:-2].strip()
                keyword = statement.split(' ', 1)[0]
                if keyword == 'for':
                    node = ['for', statement[3:].strip(), []]
                    stack[-1].append(node)
                    stack.append(node[2])
                elif keyword == 'if':
                    node = ['if', [(statement[2:].strip(), [])]]
                    stack[-1].append(node)
                    stack.append(node[1][0][1])
                elif keyword in ('elif', 'else'):
                    stack.pop()
                    node = self._enclosing_if(stack)
                    if node is None:
                        continue
                    condition = statement[4:].strip() if keyword == 'elif' else 'True'
                    node[1].append((condition, []))
                    stack.append(node[1][-1][1])
                elif keyword in ('endfor', 'endif'):
                    if len(stack) > 1:
                        stack.pop()
                elif keyword == 'set':
                    stack[-1].append(('set', statement[3:].strip()))
                else:
                    continue
            else:
                stack[-1].append(('text', token))
        return stack[0]

    @staticmethod
    def _enclosing_if(stack):
        current = stack[-1]
        for node in reversed(current):
            if isinstance(node, list) and node[0] == 'if':
                return node
        return None

    def render(self, context: dict) -> str:
        out: list = []
        self._render_nodes(self.nodes, dict(context or {}), out)
        return ''.join(out)

    def _render_nodes(self, nodes, scope, out):
        for node in nodes:
            if isinstance(node, tuple):
                kind, payload = node
                if kind == 'text':
                    out.append(payload)
                elif kind == 'var':
                    out.append(_as_docx_text(evaluate(payload, scope)))
                elif kind == 'set':
                    name, _, expr = payload.partition('=')
                    scope[name.strip()] = evaluate(expr.strip(), scope)
            elif node[0] == 'for':
                self._render_for(node, scope, out)
            elif node[0] == 'if':
                for condition, body in node[1]:
                    if truthy(evaluate(condition, scope)):
                        self._render_nodes(body, scope, out)
                        break

    def _render_for(self, node, scope, out):
        statement = node[1]
        match = re.match(r'^(.+?)\s+in\s+(.+)$', statement, re.S)
        if not match:
            return
        names = [n.strip() for n in match.group(1).split(',')]
        iterable = evaluate(match.group(2).strip(), scope)
        if iterable is None:
            return
        try:
            items = list(iterable)
        except TypeError:
            return
        total = len(items)
        for index, item in enumerate(items):
            inner = dict(scope)
            if len(names) == 1:
                inner[names[0]] = item
            else:
                try:
                    for name, value in zip(names, item):
                        inner[name] = value
                except TypeError:
                    inner[names[0]] = item
            inner['loop'] = LoopInfo(index, total)
            self._render_nodes(node[2], inner, out)


class LoopInfo:
    def __init__(self, index, length):
        self.index0 = index
        self.index = index + 1
        self.first = index == 0
        self.last = index == length - 1
        self.length = length
        self.revindex = length - index
        self.revindex0 = length - index - 1


class _Lookup(dict):
    """Name resolution that also allows attribute access on dicts."""

    def __missing__(self, key):
        return Missing()


class Missing:
    def __getattr__(self, item):
        return self

    def __getitem__(self, item):
        return self

    def __iter__(self):
        return iter(())

    def __bool__(self):
        return False

    def __str__(self):
        return ''

    def __eq__(self, other):
        return isinstance(other, Missing) or other in (None, '', False)

    def __hash__(self):
        return hash('')


class Wrapper:
    """Wraps a mapping so ``a.b`` works as well as ``a['b']``."""

    __slots__ = ('_data',)

    def __init__(self, data):
        object.__setattr__(self, '_data', data)

    def __getattr__(self, item):
        try:
            return wrap(self._data[item])
        except (KeyError, TypeError):
            value = getattr(self._data, item, Missing())
            return wrap(value)

    def __getitem__(self, item):
        try:
            return wrap(self._data[item])
        except (KeyError, IndexError, TypeError):
            return Missing()

    def __iter__(self):
        return iter(wrap(v) for v in self._data)

    def __len__(self):
        return len(self._data)

    def __contains__(self, item):
        return item in self._data

    def __str__(self):
        return str(self._data)

    def __bool__(self):
        return bool(self._data)


def wrap(value):
    if isinstance(value, dict):
        return Wrapper(value)
    if isinstance(value, (list, tuple)):
        return [wrap(v) for v in value]
    return value


FILTERS = {
    'upper': lambda v, *a: str(v).upper(),
    'lower': lambda v, *a: str(v).lower(),
    'title': lambda v, *a: str(v).title(),
    'capitalize': lambda v, *a: str(v).capitalize(),
    'trim': lambda v, *a: str(v).strip(),
    'length': lambda v, *a: len(v) if hasattr(v, '__len__') else 0,
    'join': lambda v, sep=', ': str(sep).join(str(x) for x in v),
    'default': lambda v, d='': d if (v is None or isinstance(v, Missing)
                                     or v == '') else v,
    'round': lambda v, n=0: round(float(v), int(n)),
    'int': lambda v, *a: int(float(v)),
    'float': lambda v, *a: float(v),
    'abs': lambda v, *a: abs(v),
    'sum': lambda v, *a: sum(v),
    'first': lambda v, *a: next(iter(v), ''),
    'last': lambda v, *a: list(v)[-1] if len(v) else '',
    'replace': lambda v, old='', new='': str(v).replace(str(old), str(new)),
    'format': lambda v, spec='': format(v, str(spec)),
}

FILTER_SPLIT_RE = re.compile(r'\|(?![^(\[]*[)\]])')


def evaluate(expression: str, scope: dict):
    expression = (expression or '').strip()
    if not expression:
        return ''
    parts = FILTER_SPLIT_RE.split(expression)
    value = _eval_python(parts[0].strip(), scope)
    for raw in parts[1:]:
        raw = raw.strip()
        match = re.match(r'^(\w+)\s*(?:\((.*)\))?$', raw, re.S)
        if not match:
            continue
        func = FILTERS.get(match.group(1))
        if func is None:
            continue
        args = []
        if match.group(2):
            for arg in _split_args(match.group(2)):
                args.append(_eval_python(arg.strip(), scope))
        try:
            value = func(value, *args)
        except Exception:
            value = ''
    return value


def _split_args(text: str):
    out = []
    depth = 0
    current = ''
    quote = None
    for ch in text:
        if quote:
            current += ch
            if ch == quote:
                quote = None
            continue
        if ch in '"\'':
            quote = ch
            current += ch
        elif ch in '([{':
            depth += 1
            current += ch
        elif ch in ')]}':
            depth -= 1
            current += ch
        elif ch == ',' and depth == 0:
            out.append(current)
            current = ''
        else:
            current += ch
    if current.strip():
        out.append(current)
    return out


def _eval_python(expression: str, scope: dict):
    if not expression:
        return ''
    names = _Lookup({k: wrap(v) for k, v in scope.items()})
    names.setdefault('true', True)
    names.setdefault('false', False)
    names.setdefault('none', None)
    try:
        return eval(expression, {'__builtins__': {}}, names)  # noqa: S307
    except Exception:
        return Missing()


def truthy(value) -> bool:
    if isinstance(value, Missing):
        return False
    return bool(value)
